using System;
using System.Collections.Generic;
using System.Linq;
using DealNight.Core;
using UnityEngine;
using UnityEngine.UIElements;
namespace DealNight.Presentation {
 [RequireComponent(typeof(UIDocument))]
 public sealed partial class TableApp:MonoBehaviour {
  UIDocument document;VisualElement root,overlay,body;Game game;Computer[] bots;int opponents=2;Difficulty difficulty=Difficulty.Normal;float nextAI,volume=.35f;bool reduced,paused,history,noAnimation;int selected=-1;int visualVersion;bool completeFirst=true;float animationPace=1.375f;AudioSource audioSource;AudioClip tick;string feedback="";
  void OnEnable(){document=GetComponent<UIDocument>();if(document.panelSettings==null){var panel=ScriptableObject.CreateInstance<PanelSettings>();panel.scaleMode=PanelScaleMode.ScaleWithScreenSize;panel.referenceResolution=new Vector2Int(1600,900);panel.screenMatchMode=PanelScreenMatchMode.MatchWidthOrHeight;panel.match=.5f;document.panelSettings=panel;}root=document.rootVisualElement;root.styleSheets.Add(Resources.Load<StyleSheet>("Table"));root.style.unityFont=Resources.Load<Font>("Interface");root.AddToClassList("app");root.EnableInClassList("touch",TouchMode);volume=PlayerPrefs.GetFloat("volume",.35f);reduced=PlayerPrefs.GetInt("reduced",0)==1;audioSource=gameObject.AddComponent<AudioSource>();tick=MakeTone();music=GetComponent<MusicPlayer>();if(music==null)music=gameObject.AddComponent<MusicPlayer>();completeFirst=PlayerPrefs.GetInt("completeFirst",1)==1;animationPace=PresentationOptions.Durations[Mathf.Clamp(PlayerPrefs.GetInt("animationStep15",PresentationOptions.MigrateSpeed(PlayerPrefs.GetFloat("animationPace",1.5f)*.65f)),0,4)];playerName=PresentationMath.PlayerName(PlayerPrefs.GetString(NameKey,""));pieceChoice=Mathf.Clamp(PlayerPrefs.GetInt("piece",0),0,PieceNames.Length-1);autoChoices=PlayerPrefs.GetInt("autoChoices",1)==1;Menu();if(playerName.Length==0)Welcome();}
  void OnApplicationFocus(bool focused){if(!focused){EndTouchPeek();HideHint();}}
  void OnDestroy(){HideHint();if(tick!=null)Destroy(tick);}
  AudioClip MakeTone(){const int n=4800;float[] samples=new float[n];for(int i=0;i<n;i++){float t=i/48000f;samples[i]=(float)(Math.Sin(t*2*Math.PI*660)*Math.Exp(-t*45)*.17);}var c=AudioClip.Create("Soft card chime",n,1,48000,false);c.SetData(samples,0);return c;}
  void Update(){if(music!=null)music.ResponseActive=noAnimation||(game!=null&&game.Phase==Phase.Reaction);UpdateMobile();if(overlay!=null){bool peek=touchPeek||(!TouchMode&&UnityEngine.Input.GetMouseButton(1));if(peek)HideHint();overlay.style.opacity=peek?0f:1f;}if(tutorial!=null){TutorialTick();return;}if(game==null||paused||noAnimation||game.Phase==Phase.GameOver||game.DecisionPlayer==0||Time.unscaledTime<nextAI)return;int actor=game.DecisionPlayer;Send(bots[actor].Choose(game.Observe(actor),game.Legal(actor)));}
  void Clear(){RemoveTouchPeek();var flying=game==null?new VisualElement[0]:root.Children().Where(e=>e.ClassListContains("motion-card")||e.ClassListContains("bank-gain")).ToArray();foreach(var motion in flying)motion.RemoveFromHierarchy();HideHint();visualVersion++;root.EnableInClassList("reduced",reduced);root.Clear();body=Widgets.Box("body");root.Add(body);foreach(var motion in flying)root.Add(motion);overlay=null;}
  void Menu(){tutorial=null;tutorialResult=null;game=null;paused=false;Clear();body.AddToClassList("main-menu");var panel=Widgets.Box("menu");body.Add(panel);panel.Add(Widgets.Text("NOISEWATER LABS  /  TABLE GAMES","eyebrow"));panel.Add(Widgets.Text(TouchMode?"DEAL NIGHT":"DEAL\nNIGHT","hero"));panel.Add(Widgets.Text("Build your fortune. Break their plans.","subtitle"));panel.Add(Widgets.Text("Version "+Application.version+" • Offline • Unofficial fan game","muted"));
   var count=new DropdownField("Opponents",new List<string>{"1","2","3","4"},opponents-1);count.RegisterValueChangedCallback(e=>opponents=int.Parse(e.newValue));panel.Add(count);var diff=new DropdownField("AI difficulty",new List<string>{"Easy","Normal","Hard"},(int)difficulty);diff.RegisterValueChangedCallback(e=>difficulty=(Difficulty)Enum.Parse(typeof(Difficulty),e.newValue));panel.Add(diff);
   panel.Add(Widgets.Button("New game  →",RequestNewGame,"primary"));panel.Add(Widgets.Button("Guided tutorial",StartTutorial));panel.Add(Widgets.Button("Rules & how to play",Rules));panel.Add(Widgets.Button("Settings",Settings));panel.Add(Widgets.Button("Quit",()=>Application.Quit()));var art=Widgets.Box("menu-art");body.Add(art);var properties=Catalog.Create().Where(c=>c.Kind==Kind.Property).ToArray();for(int i=0;i<3;i++){int j=UnityEngine.Random.Range(i,properties.Length);var swap=properties[i];properties[i]=properties[j];properties[j]=swap;art.Add(Widgets.Card(properties[i],()=>{},false));}}
  void StartGame(){tutorial=null;tutorialResult=null;foreach(var motion in root.Children().Where(e=>e.ClassListContains("motion-card")||e.ClassListContains("bank-gain")).ToArray())motion.RemoveFromHierarchy();mobilePages.Clear();int seed=Environment.TickCount;game=new Game(opponents+1,seed,playerName);AssignPieces();bots=Enumerable.Range(0,opponents+1).Select(i=>new Computer(difficulty,seed+i+100)).ToArray();arrivals.Clear();selected=-1;paused=false;feedback="Collect three complete sets in different colors.";nextAI=Time.unscaledTime+.65f;Render();}
  void Send(Command c){if(game==null||noAnimation)return;if(tutorial!=null&&!TutorialAllows(c))return;string error;var before=CaptureCards();var bankBefore=Enumerable.Range(0,game.Players.Count).Select(game.BankTotal).ToArray();if(!game.Execute(c,out error)){feedback=error;Render();return;}if(tutorial!=null){tutorialResult=tutorial.Current.Result;tutorialResultShown=false;tutorialLastCard=c.Card;}MarkArrivals(before);audioSource.PlayOneShot(tick,volume);selected=-1;feedback=c.Op==Op.Pay?"Payment complete. No change is given.":game.History.LastOrDefault()??"";nextAI=Time.unscaledTime+(reduced?.12f:1.1f*animationPace);if(c.Op==Op.No){noAnimation=true;Render();ShowNo(game.Players[c.Actor].Name);}else{Render();if(!reduced)AnimateChanges(c,before);for(int i=0;i<game.Players.Count;i++){int player=i,delta=game.BankTotal(i)-bankBefore[i];if(delta>0)root.schedule.Execute(()=>BankGain(player,delta)).StartingIn(20);}}}
  void Render(){if(tutorialResult!=null)tutorialResultShown=false;Clear();if(game.Phase==Phase.GameOver){Victory();return;}var top=Widgets.Box("topbar");body.Add(top);top.Add(Widgets.Text("DEAL NIGHT","brand"));top.Add(Widgets.Text("v"+Application.version,"build-version"));top.Add(PlayerBadge(game.Current,"turn"," • Turn "+game.Turn));top.Add(Widgets.Button("History",()=>{history=!history;Render();},"header-history"));top.Add(Widgets.Button("Pause",Pause));
   var table=Widgets.Box("table");body.Add(table);var enemies=Widgets.Box("opponents");table.Add(enemies);for(int i=1;i<game.Players.Count;i++)enemies.Add(PlayerArea(i));
   var center=Widgets.Box("center-strip");table.Add(center);center.Add(Widgets.Text("DRAW\n"+game.Deck.Count,"pile"));var last=game.Discard.Count>0?game.Cards[game.Discard.Last()].Name:"Empty";center.Add(Widgets.Text("DISCARD\n"+last,"discard-pile"));var info=Widgets.Box("status");center.Add(info);info.Add(PlayerText(feedback,"feedback"));info.Add(Widgets.Text(game.Phase==Phase.Playing?(game.Current==0?(game.Remaining==0?"No plays left • End your turn when ready.":"Select a card to play or bank."):"Opponent is thinking…"):game.Phase.ToString(),"muted"));
   table.Add(PlayerArea(0));var bottom=Widgets.Box("hand-zone");body.Add(bottom);var handTop=Widgets.Box("row");bottom.Add(handTop);handTop.Add(Widgets.Text("YOUR HAND  /  "+game.Players[0].Hand.Count,"eyebrow"));handTop.Add(Widgets.Text(game.Current==0?game.Remaining+" "+(game.Remaining==1?"Play left":"Plays left"):"Opponent’s turn","hand-plays"));var end=Widgets.Button("End turn",()=>Send(new Command(Op.End,0)),"primary");end.SetEnabled(game.Current==0&&game.Phase==Phase.Playing);handTop.Add(end);var hand=Widgets.Box("fit-hand");hand.EnableInClassList("hand-exhausted",game.Current==0&&game.Remaining==0);bottom.Add(hand);
   foreach(int id in game.Players[0].Hand){int cardId=id;var card=Widgets.Card(game.Cards[id],()=>Inspect(cardId));card.name="handcard-"+id;if(arrivals.ContainsKey(id)){card.style.opacity=0;card.SetEnabled(false);}card.RegisterCallback<PointerDownEvent>(e=>{card.userData=e.position;});card.RegisterCallback<PointerUpEvent>(e=>{if(card.userData is Vector3&&((Vector3)card.userData).y-e.position.y>45)Inspect(cardId);});hand.Add(card);}
   FitChildren(hand,170,215,TouchMode?.88f:1f);
   AddTutorialBar();
   if(tutorialResult!=null)return;
   if(history){var h=Modal("Action history",false);var scroll=new ScrollView();h.Add(scroll);foreach(string line in game.History.AsEnumerable().Reverse())scroll.Add(PlayerText(line,"history-line"));h.Add(Widgets.Button("Close",Close));}
   else if(!noAnimation&&game.DecisionPlayer==0&&game.Phase==Phase.Reaction)Reaction();else if(game.DecisionPlayer==0&&game.Phase==Phase.Payment)Payment();else if(game.DecisionPlayer==0&&game.Phase==Phase.Discarding)DiscardUI();
  }
  VisualElement Modal(string title,bool close=true){RemoveTouchPeek();HideHint();if(overlay!=null)overlay.RemoveFromHierarchy();overlay=Widgets.Box("overlay");root.Add(overlay);var window=Widgets.Box("modal");overlay.Add(window);AddPeekHint(window);var row=Widgets.Box("row");window.Add(row);row.Add(Widgets.Text(title,"modal-title"));if(close)row.Add(Widgets.Button("×",Close));if(!reduced){window.style.opacity=0;window.schedule.Execute(()=>window.style.opacity=1).StartingIn(16);}AddTouchPeek();return window;}
  void Close(){RemoveTouchPeek();if(overlay!=null)overlay.RemoveFromHierarchy();overlay=null;history=false;if(game!=null&&!paused&&game.DecisionPlayer==0&&(game.Phase==Phase.Reaction||game.Phase==Phase.Payment||game.Phase==Phase.Discarding))Render();}
  void Confirm(Command c,Action back=null){if(c.Op==Op.Bank||c.Op==Op.Discard||(c.Op==Op.Play&&game.Cards[c.Card].Property)){Send(c);return;}var w=Modal("Confirm action");w.Add(PlayerText(ActionSummary(c),"description"));if(c.Set>=0){var referenced=game.Players.SelectMany(p=>p.Sets).FirstOrDefault(s=>s.Id==c.Set);if(referenced!=null)MiniCards(w,referenced.Cards);}if(c.Take>=0){var preview=Widgets.Box("trade-preview");w.Add(preview);var take=Widgets.Box("trade-side");take.Add(Widgets.Text("YOU RECEIVE","eyebrow"));take.Add(Widgets.Card(game.Cards[c.Take],()=>{}));preview.Add(take);if(c.Give>=0){var give=Widgets.Box("trade-side");give.Add(Widgets.Text("YOU GIVE","eyebrow"));give.Add(Widgets.Card(game.Cards[c.Give],()=>{}));preview.Add(give);}}w.Add(Widgets.Text(c.Op==Op.Move?(game.Cards[c.Card].Kind==Kind.Wild&&AssignedColor(c.Card)!=c.Color?"Uses 1 play to rotate this wildcard.":"Free rearrangement."):"Uses "+(1+c.Extras.Length)+((1+c.Extras.Length)==1?" play.":" plays."),"muted"));w.Add(Widgets.Button("Confirm",()=>Send(c),"primary"));w.Add(Widgets.Button("Back",back??(Action)Close));}
  void BankInspect(int player){var w=Modal("Bank");w.Add(PlayerBadge(player));w.Add(Widgets.Text("These cards permanently act as money.","description"));var grid=Grid(w);foreach(int id in game.Players[player].Bank)grid.Add(Widgets.BankCard(game.Cards[id],()=>{}));w.Add(Widgets.Button("Back to table",Close));}
  void DiscardUI(){var w=Modal("Discard to seven • "+(game.Players[0].Hand.Count-7)+" remaining",false);w.Add(Widgets.Text("Your turn cannot finish until you have seven cards. Click a card to discard it; repeat until the required number is removed.","description"));var grid=Grid(w);foreach(var cmd in game.Legal(0)){var c=cmd;grid.Add(Widgets.Card(game.Cards[c.Card],()=>Send(c)));}}
  void Pause(){paused=true;var w=Modal("Paused",false);w.Add(Widgets.Button("Resume",()=>{paused=false;Render();},"primary"));w.Add(Widgets.Button("Settings",Settings));w.Add(Widgets.Button("Rules",Rules));w.Add(Widgets.Button("Main menu",()=>{var confirm=Modal("Leave this match?",false);confirm.Add(Widgets.Text("This match is not saved.","description"));confirm.Add(Widgets.Button("Leave match",Menu));confirm.Add(Widgets.Button("Keep playing",()=>{paused=false;Render();}));}));}
  void Settings(){var w=Modal("Settings • v"+Application.version,false);{var scroll=new ScrollView();scroll.AddToClassList("mobile-settings");w.Add(scroll);w=scroll.contentContainer;}var nameField=NameField(w);PiecePicker(w);AddBoardSettings(w);w.Add(Widgets.Button("Music & soundtrack",()=>{if(PresentationMath.PlayerName(nameField.value).Length>0)SaveName(nameField.value);MusicSettings();}));var vol=new Slider("Card sound volume",0,1){value=volume};vol.RegisterValueChangedCallback(e=>{volume=e.newValue;PlayerPrefs.SetFloat("volume",volume);});w.Add(vol);var motion=new Toggle("Reduced motion"){value=reduced};motion.RegisterValueChangedCallback(e=>{reduced=e.newValue;root.EnableInClassList("reduced",reduced);PlayerPrefs.SetInt("reduced",reduced?1:0);});w.Add(motion);var full=new Toggle("Fullscreen"){value=Screen.fullScreen};full.RegisterValueChangedCallback(e=>Screen.fullScreen=e.newValue);if(!TouchMode)w.Add(full);var done=Widgets.Button("Done",()=>{SaveName(nameField.value);PlayerPrefs.Save();if(game!=null&&paused)Pause();else Menu();},"primary");w.Add(done);nameField.RegisterValueChangedCallback(e=>done.SetEnabled(PresentationMath.PlayerName(e.newValue).Length>0));}
  void Rules(){IllustratedRules();}
  void Victory(){var w=Widgets.Box("victory");body.Add(w);w.Add(Widgets.Text("MATCH COMPLETE","eyebrow"));w.Add(PlayerBadge(game.Winner,"result-title"," wins"));w.Add(Widgets.Text(game.Turn+" turns played","muted"));var sets=Widgets.Box("winning-sets");w.Add(sets);
   foreach(var set in game.Players[game.Winner].Sets.Where(game.Complete).GroupBy(s=>s.Color).Select(g=>g.First()).Take(3)){var tile=Widgets.Box("winning-set");Widgets.Tint(tile,Widgets.GroupColor(set.Color));tile.Add(Widgets.Text(Catalog.Labels[(int)set.Color],"modal-title"));MiniCards(tile,set.Cards);sets.Add(tile);}
   var stats=Widgets.Box("result-stats");w.Add(stats);var heading=Widgets.Box("stat-row");heading.Add(Widgets.Text("Player","stat-name"));foreach(var label in new[]{"Plays","Drawn","Actions","Nos","Banked","Received","Paid","Overpaid","Taken","Discarded","Sets"})heading.Add(Widgets.Text(label,"stat-value"));stats.Add(heading);foreach(var p in game.Players){var row=Widgets.Box("stat-row");row.Add(PlayerBadge(game.Players.IndexOf(p),"stat-name"));foreach(var value in new[]{p.Plays.ToString(),p.Drawn.ToString(),p.Actions.ToString(),p.Nos.ToString(),p.Banked+"M",p.Received+"M",p.Payments+"M",p.Overpaid+"M",p.Stolen.ToString(),p.Discarded.ToString(),game.CompleteCount(game.Players.IndexOf(p)).ToString()})row.Add(Widgets.Text(value,"stat-value"));stats.Add(row);}var most=game.Players.OrderByDescending(p=>p.Overpaid).First();w.Add(PlayerText(most.Overpaid>0?"Most overpaid: "+most.Name+" • "+most.Overpaid+"M total • largest payment excess "+most.LargestOverpayment+"M":"No overpayments this match","muted"));w.Add(Widgets.Button("Play again",StartGame,"primary"));w.Add(Widgets.Button("Main menu",Menu));}

 }
}
